import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]*$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String sortColumn = req.getParameter("sort");
        String filterDate = req.getParameter("from_date");
        String customerId = req.getParameter("customer_id");

        // Validate report type against whitelist
        if (reportType == null || !isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate sort column - only allow identifier characters
        if (sortColumn != null && !SAFE_IDENTIFIER.matcher(sortColumn).matches()) {
            sortColumn = "created_at"; // default fallback
        }
        if (sortColumn == null) sortColumn = "created_at";

        // Build query - sortColumn is validated above, but filterDate is not
        // The developer assumed filterDate would be validated by the frontend
        String query = buildReportQuery(reportType, sortColumn, filterDate, customerId);

        try {
            Connection conn = getConnection();
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnName(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

            rs.close();
            stmt.close();
            conn.close();
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private String buildReportQuery(String type, String sort, String filterDate, String customerId) {
        String baseTable = getTableForType(type);
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM ").append(baseTable);
        sb.append(" WHERE 1=1");

        if (customerId != null) {
            // customerId is used with prepared-statement-style quoting
            sb.append(" AND customer_id = '").append(customerId.replace("'", "''")).append("'");
        }

        if (filterDate != null) {
            // VULNERABILITY: filterDate is concatenated without sanitization
            sb.append(" AND created_at >= '").append(filterDate).append("'");
        }

        sb.append(" ORDER BY ").append(sort).append(" DESC LIMIT 1000");
        return sb.toString();
    }

    private boolean isValidReportType(String type) {
        return type.equals("sales") || type.equals("inventory") || 
               type.equals("customers") || type.equals("orders");
    }

    private String getTableForType(String type) {
        switch(type) {
            case "sales": return "report_sales";
            case "inventory": return "report_inventory";
            case "customers": return "report_customers";
            case "orders": return "report_orders";
            default: return "report_sales";
        }
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }
}
